#!/usr/bin/env bash
# Re-resolve env/<role>-requirements.in into the pinned env/<role>-requirements.txt.
#
# Usage: make lock   (loads env/modules.sh and passes PIP_FLAGS)
set -euo pipefail

role="$1"
root="$(cd "$(dirname "$0")/.." && pwd)"
tmp="${root}/.venv/_lock-${role}"

rm -rf "$tmp"
python3 -m venv "$tmp"
# PIP_FLAGS is intentionally unquoted: it holds several flags.
"$tmp/bin/python" -m pip install ${PIP_FLAGS:?run via make lock} -r "${root}/env/${role}-requirements.in"
{
    echo "# Generated by 'make lock' from env/${role}-requirements.in with $(python3 --version). Do not edit."
    "$tmp/bin/python" -m pip freeze
} > "${root}/env/${role}-requirements.txt"
rm -rf "$tmp"
